        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Primarie, Conte in campo. Si lavora già alla campagna",
        "testo_it": "Giuseppe Conte annuncia la candidatura alle primarie del M5S, puntando al coinvolgimento della società civile.",
        "priorita": "Bassa",
